#[test]
fn test_derive_emits_fieldless_enum_metadata() {
    let metadata = metadata_of::<Status>();

    assert!(matches!(metadata.kind(), TypeKind::Enum(enum_metadata)
        if enum_metadata.variants().len() == 2
            && enum_metadata.variants()[0].name() == "DRAFT"
            && enum_metadata.variants()[1].ordinal() == 1));
}

#[test]
fn test_derive_emits_data_enum_variant_metadata() {
    let TypeKind::Enum(metadata) = metadata_of::<Event>().kind() else {
        panic!("Event should have enum metadata");
    };
    let variants = metadata.variants();

    assert!(matches!(variants[0].kind(), EnumVariantKind::Unit));
    assert!(matches!(variants[1].kind(), EnumVariantKind::Tuple(_)));
    assert_eq!(variants[1].fields().len(), 2);
    assert_eq!(variants[1].fields()[0].name(), "0");
    assert_eq!(variants[1].fields()[1].name(), "1");
    assert!(matches!(variants[2].kind(), EnumVariantKind::Tuple(_)));
    assert!(matches!(variants[3].kind(), EnumVariantKind::Tuple(_)));
    assert!(matches!(variants[4].kind(), EnumVariantKind::Struct(_)));
    let message = variants[4].fields()[0];
    assert_eq!(message.name(), "message");
    assert_eq!(message.text_constraint().and_then(|text| text.max_chars()), Some(200));
}

#[test]
fn test_data_enum_generates_names_display_and_serde_defaults() {
    let progress = Event::Progress(42, "items".to_owned());
    let failed = Event::Failed {
        message: "timeout".to_owned(),
        details: None,
        tags: Vec::new(),
    };

    assert_eq!(progress.name(), "PROGRESS");
    assert_eq!(progress.to_string(), "PROGRESS(42, \"items\")");
    assert_eq!(
        failed.to_string(),
        "FAILED { message: \"timeout\", details: None, tags: [] }"
    );
    assert_eq!(
        serde_json::to_string(&failed).expect("data enum should serialize"),
        r#"{"FAILED":{"error_message":"timeout"}}"#
    );
}

#[test]
fn test_data_enum_preserves_non_trailing_tuple_field_positions() {
    let required_tail = Event::Optional(None, vec!["tag".to_owned()]);
    let optional_tail = Event::OptionalValues(None, Some("tail".to_owned()));

    assert_eq!(
        serde_json::to_string(&required_tail).expect("tuple data enum should serialize"),
        r#"{"OPTIONAL":[null,["tag"]]}"#
    );
    assert_eq!(
        serde_json::to_string(&optional_tail).expect("tuple data enum should serialize"),
        r#"{"OPTIONAL_VALUES":[null,"tail"]}"#
    );
    assert_eq!(
        serde_json::from_str::<Event>(r#"{"OPTIONAL_VALUES":[null,"tail"]}"#)
            .expect("tuple data enum should deserialize"),
        optional_tail
    );
}

#[test]
fn test_data_enum_omits_trailing_tuple_fields_with_defaults() {
    let optional = Event::Optional(None, Vec::new());
    let serialized = serde_json::to_string(&optional).expect("tuple data enum should serialize");

    assert_eq!(serialized, r#"{"OPTIONAL":[null]}"#);
    assert_eq!(
        serde_json::from_str::<Event>(&serialized).expect("tuple data enum should deserialize"),
        optional,
    );
}

#[test]
fn test_enum_name_methods_follow_serde_serialization_names() {
    assert_eq!(SerializedStatus::Reviewing.name(), "reviewing");
    assert_eq!(
        SerializedStatus::from_name("reviewing"),
        Some(SerializedStatus::Reviewing)
    );
    assert_eq!(SerializedStatus::Invalid.name(), "invalid-state");
    assert_eq!(
        SerializedStatus::from_name("invalid-state"),
        Some(SerializedStatus::Invalid)
    );
    assert_eq!(SerializedStatus::from_name("invalid"), None);
}

#[test]
fn test_model_attributes_expand_in_canonical_form() {
    let metadata = metadata_of::<AttributedModel>();

    let primary_key = metadata.primary_key().expect("primary key metadata");
    assert_eq!(
        primary_key
            .fields()
            .iter()
            .map(|field| (field.name(), field.is_generated()))
            .collect::<Vec<_>>(),
        [("id", true)]
    );
    let unique = metadata.unique_constraints().next().expect("unique metadata");
    assert_eq!(unique.name(), Some("organization_username"));
    assert_eq!(unique.comparison_of("organization_id"), Some(UniqueComparison::Exact));
    assert_eq!(unique.comparison_of("username"), Some(UniqueComparison::IgnoreCase));
    let index = metadata
        .indexes()
        .find(|index| index.name() == Some("created_at_index"))
        .expect("created-at index metadata");
    assert_eq!(index.name(), Some("created_at_index"));
    assert_eq!(index.fields(), &["created_at"]);
    assert!(metadata.indexes().any(|index| index.fields() == ["organization_id"]));
    assert!(matches!(
        metadata.attribute(AttributeKind::Key),
        Some(AttributeMetadata::Key(key))
            if key.name() == Some("account") && key.contains("username")
    ));
    assert!(matches!(
        metadata.attribute(AttributeKind::Ownership),
        Some(AttributeMetadata::Ownership(ownership))
            if ownership.owner().identity().type_name()
                == core::any::type_name::<Organization>()
    ));
}

#[test]
fn test_text_sequence_and_map_attributes_expand() {
    let metadata = metadata_of::<AttributedModel>();
    let text = metadata
        .field("username")
        .expect("username metadata")
        .text_constraint()
        .expect("text constraint");
    assert_eq!(text.min_chars(), Some(3));
    assert_eq!(text.max_chars(), Some(32));
    assert_eq!(text.min_bytes(), Some(3));
    assert_eq!(text.max_bytes(), Some(64));
    assert_eq!(text.allowed_chars(), AllowedChars::Ascii);
    assert!(text.is_non_blank());
    assert_eq!(text.format(), Some(TextFormat::Email));

    assert!(matches!(
        metadata
            .field("aliases")
            .expect("aliases metadata")
            .attribute(AttributeKind::Sequence),
        Some(AttributeMetadata::Sequence(sequence))
            if sequence.min_items() == Some(1)
                && sequence.max_items() == Some(5)
                && sequence.has_unique_items()
    ));
    assert!(matches!(
        metadata
            .field("labels")
            .expect("labels metadata")
            .attribute(AttributeKind::Map),
        Some(AttributeMetadata::Map(map))
            if map.min_entries() == Some(1) && map.max_entries() == Some(4)
    ));
}

#[test]
fn test_temporal_decimal_and_money_attributes_expand() {
    let metadata = metadata_of::<AttributedModel>();

    assert!(matches!(
        metadata
            .field("created_at")
            .expect("created_at metadata")
            .attribute(AttributeKind::Temporal),
        Some(AttributeMetadata::Temporal(temporal))
            if temporal.precision() == TemporalPrecision::Millisecond
    ));
    assert!(matches!(
        metadata
            .field("ratio")
            .expect("ratio metadata")
            .attribute(AttributeKind::Decimal),
        Some(AttributeMetadata::Decimal(decimal))
            if decimal.precision() == Some(8)
                && decimal.scale() == 3
                && decimal.rounding() == RoundingMode::HalfUp
                && decimal.semantic() == DecimalSemantic::Number
    ));
    assert!(matches!(
        metadata
            .field("balance")
            .expect("balance metadata")
            .attribute(AttributeKind::Decimal),
        Some(AttributeMetadata::Decimal(decimal))
            if decimal.precision() == Some(12)
                && decimal.scale() == 2
                && decimal.rounding() == RoundingMode::HalfEven
                && decimal.semantic() == DecimalSemantic::Money
    ));
}

#[test]
fn test_migrated_element_and_mobile_constraints_expand() {
    let metadata = metadata_of::<AttributedModel>();
    let ascii_element = metadata
        .field("ascii_codes")
        .expect("ascii_codes metadata")
        .element_metadata()
        .expect("ASCII element metadata");
    assert!(matches!(
        ascii_element.attributes(),
        [AttributeMetadata::Text(text)]
            if text.allowed_chars() == AllowedChars::Ascii
    ));

    let decimal_element = metadata
        .field("decimal_values")
        .expect("decimal_values metadata")
        .element_metadata()
        .expect("decimal element metadata");
    assert!(matches!(
        decimal_element.attributes(),
        [AttributeMetadata::Decimal(decimal)]
            if decimal.scale() == 2
                && decimal.semantic() == DecimalSemantic::Number
    ));

    assert_eq!(
        metadata
            .field("mobile")
            .expect("mobile metadata")
            .text_constraint()
            .and_then(|text| text.format()),
        Some(TextFormat::Mobile)
    );
}

#[test]
fn test_reference_and_strategy_attributes_expand() {
    let metadata = metadata_of::<AttributedModel>();
    let reference = metadata
        .field("organization_id")
        .expect("organization_id metadata")
        .reference()
        .expect("reference metadata");
    assert_eq!(reference.entity().as_str(), "test.derive.Organization");
    assert_eq!(reference.target(), ReferenceTarget::Property(FieldPath::new(&["id"])));
    assert!(reference.existing());
    assert_eq!(
        reference.path().expect("reference path").segments(),
        &[
            ReferencePathSegment::Field("organization"),
            ReferencePathSegment::Field("id"),
        ]
    );

    let whole_reference = metadata
        .field("organization")
        .expect("organization metadata")
        .reference()
        .expect("whole model reference metadata");
    assert_eq!(whole_reference.entity().as_str(), "test.derive.Organization");
    assert_eq!(whole_reference.target(), ReferenceTarget::WholeModel);
    assert!(whole_reference.existing());
    assert_eq!(whole_reference.path(), None);

    let lookup = metadata
        .field("organization_lookup")
        .expect("organization lookup metadata")
        .lookup_relation()
        .expect("lookup relation metadata");
    assert_eq!(
        lookup.target().identity().type_name(),
        core::any::type_name::<Organization>()
    );
    assert_eq!(lookup.target_field().segments(), &["id"]);

    let secret = metadata.field("secret").expect("secret metadata");
    assert!(matches!(
        secret.attribute(AttributeKind::Codec),
        Some(AttributeMetadata::Codec(codec)) if codec.name() == "encrypted"
    ));
    assert!(matches!(
        secret.attribute(AttributeKind::Generator),
        Some(AttributeMetadata::Generator(generator))
            if generator.name() == "account_balance"
    ));
}

#[allow(dead_code)]
#[Model(
    id = "test.derive.ReferenceWithOpaqueForeignKey",
    no_clone,
    no_debug,
    no_display,
    no_partial_eq,
    no_hash,
    no_serialize,
    no_deserialize
)]
struct ReferenceWithOpaqueForeignKey {
    #[reference(entity = "test.derive.Organization", property = id)]
    organization_id: std::path::PathBuf,
}

#[test]
fn test_reference_field_auto_opaque_for_non_has_type_shape() {
    let metadata = metadata_of::<ReferenceWithOpaqueForeignKey>();
    let field = metadata.field("organization_id").expect("organization_id metadata");
    assert!(matches!(field.field_type().shape(), TypeShape::Opaque));
    assert_eq!(
        field.field_type().type_name(),
        core::any::type_name::<std::path::PathBuf>()
    );

    let organization = metadata_of::<AttributedModel>()
        .field("organization")
        .expect("organization metadata");
    assert!(matches!(organization.field_type().shape(), TypeShape::Named(_)));
}

#[test]
fn test_derive_registers_every_supported_shape_and_legacy_macro() {
    let registry = ModelRegistry::try_global().expect("the test models should register without duplicate IDs");
    for (id, rust_type_name) in [
        ("test.derive.User", "User"),
        ("test.derive.Empty", "Empty"),
        ("test.derive.UserId", "UserId"),
        ("test.derive.Status", "Status"),
    ] {
        let registration = registry
            .registration(id)
            .unwrap_or_else(|| panic!("the model with ID {id} should be registered"));
        assert_eq!(registration.metadata().id().as_str(), id);
        assert_eq!(registration.rust_type_name(), rust_type_name);
    }
}

#[test]
fn test_derive_exposes_explicit_model_registration() {
    let registration = Status::model_registration();

    assert_eq!(registration.id().as_str(), "test.derive.Status");
    assert!(core::ptr::eq(registration.metadata(), metadata_of::<Status>(),));
}

#[test]
fn test_opaque_field_does_not_require_has_type_shape() {
    let field = metadata_of::<AttributedModel>()
        .field("external")
        .expect("external metadata");

    assert!(matches!(field.field_type().shape(), TypeShape::Opaque));
    assert_eq!(field.field_type().type_name(), core::any::type_name::<ExternalValue>());
}
